// A TypeScript lib written for the tracer's tests (log/trace-core-plan.md, Task 6): the shapes the language's own
// objects and a host have in a real lib — generic containers, iterators and generators, promises, the intrinsics of
// objects and functions with `this` parameters, variadic and conditional types, property descriptors, an event target,
// a timer — in the tests' own words. The fixtures under `fixture/` read it as their default lib (no target written: TypeScript 5's).
interface Step<T> { done?: boolean; value: T; }
interface Iterator<T> { next(): Step<T>; }
interface IterableIterator<T> extends Iterator<T> { [Symbol.iterator](): IterableIterator<T>; }
interface Generator<T> extends IterableIterator<T> { [Symbol.iterator](): Generator<T>; }

interface Array<T> {
  length: number;
  [n: number]: T;
  push(...items: T[]): number;
  forEach(callbackfn: (value: T, index: number, array: T[]) => void): void;
  map<U>(callbackfn: (value: T, index: number, array: T[]) => U): U[];
  [Symbol.iterator](): IterableIterator<T>;
}

interface ReadonlyMap<K, V> {
  get(key: K): V | undefined;
  forEach(callbackfn: (value: V, key: K, map: ReadonlyMap<K, V>) => void): void;
  [Symbol.iterator](): IterableIterator<[K, V]>;
}
interface Map<K, V> extends ReadonlyMap<K, V> { set(key: K, value: V): this; }
interface MapConstructor { new <K, V>(): Map<K, V>; }
declare var Map: MapConstructor;

interface Thenable<T> { then<R>(onfulfilled: (value: T) => R | Thenable<R>): Thenable<R>; }
interface Promise<T> { then<R>(onfulfilled: (value: T) => R | Thenable<R>): Promise<R>; }
interface PromiseConstructor { resolve<T>(value: T): Promise<T>; }
declare var Promise: PromiseConstructor;

interface Object { toString(): string; }
type PropertyKey = string | number | symbol;
interface PropertyDescriptor { configurable?: boolean; enumerable?: boolean; value?: any; writable?: boolean;
  get?(): any; set?(v: any): void; }
interface PropertyDescriptorMap { [key: PropertyKey]: PropertyDescriptor; }
interface ThisType<T> {}
interface ObjectConstructor {
  defineProperty<T>(o: T, p: PropertyKey, attributes: PropertyDescriptor & ThisType<any>): T;
  defineProperties<T>(o: T, properties: PropertyDescriptorMap & ThisType<any>): T;
  keys(o: object): string[];
  values<T>(o: { [key: string]: T }): T[];
  entries<T>(o: { [key: string]: T }): [string, T][];
}
declare var Object: ObjectConstructor;

type ThisOf<T> = T extends (this: infer U, ...args: never) => any ? U : unknown;
type WithoutThis<T> = unknown extends ThisOf<T> ? T : T extends (...args: infer A) => infer R ? (...args: A) => R : T;
interface Function { readonly length: number; }
interface CallableFunction extends Function {
  call<T, A extends any[], R>(this: (this: T, ...args: A) => R, thisArg: T, ...args: A): R;
  apply<T, A extends any[], R>(this: (this: T, ...args: A) => R, thisArg: T, args: A): R;
  bind<T>(this: T, thisArg: ThisOf<T>): WithoutThis<T>;
}

interface Event { readonly type: string; }
declare var Event: { new (type: string): Event };
interface EventListener { (event: Event): void; }
interface EventListenerObject { handleEvent(event: Event): void; }
type EventListenerOrEventListenerObject = EventListener | EventListenerObject;
interface EventTarget {
  addEventListener(type: string, listener: EventListenerOrEventListenerObject | null): void;
  dispatchEvent(event: Event): boolean;
}
declare var EventTarget: { new (): EventTarget };
type TimerHandler = string | Function;
interface Window extends EventTarget { setTimeout(handler: TimerHandler, timeout?: number): number; }
declare var window: Window;
